script.text:
			&OutlineEntry;
			/* <flatten type="Javascript"> */
function active$VoucherFilter$(sender) {sender.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(sender, 'ma_dvcs');
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, k = new Array()
				, dv = $func.trim(f.getItemValue('ma_dvcs'))
				, _nh_vv1 = $func.trim(f.getItemValue('nh_vv1'))
				, _nh_hd1 = $func.trim(f.getItemValue('nh_hd1'))
				, _nh_hd2 = $func.trim(f.getItemValue('nh_hd2'))
				, _nh_hd3 = $func.trim(f.getItemValue('nh_hd3'));

			if (_nh_vv1) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_vv1, \'' + _nh_vv1 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_hd1) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd1, \'' + _nh_hd1 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_hd2) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd2, \'' + _nh_hd2 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_hd3) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd3, \'' + _nh_hd3 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (dv) Array.add(k, {Name: 'dbo.ff_ExactInlist(list_dvcs, \'' + dv + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});

			g.set_externalKey(k);
			break;
		default:
				break;
	}
}
/* </flatten> */
